def algorithm(func, dim, lb, ub, budget, rng):
    def mutate(x, sigma=0.5):
        return x + rng.normal(size=(dim,)) * sigma

    def select(population, f_values, k):
        indices = np.argsort(f_values)[:k]
        return population[indices], f_values[indices]

    population = rng.uniform(lb, ub, size=(budget, dim))
    f_values = [func(x) for x in population]

    for _ in range(budget - 1):
        parents, _ = select(population, f_values, budget // 2)

        children = []
        for i in range(0, len(parents), 2):
            parent1, parent2 = parents[i], parents[i + 1]
            child = (parent1 + parent2) / 2.0
            child = mutate(child)
            children.append(np.clip(child, lb, ub))

        population = np.concatenate((population, children))
        f_values = [func(x) for x in population]

    best_idx = np.argmin(f_values)
    return np.clip(population[best_idx], lb, ub)

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    def evaluate(x):
        return func(clip(x))

    x = np.random.uniform(lb, ub, size=dim)
    t = 1.0
    best_x = x.copy()
    best_f = evaluate(best_x)
    for _ in range(budget):
        sigma = (ub - lb) / np.sqrt(t)
        delta = rng.normal(size=dim, loc=0.0, scale=sigma)
        new_x = clip(x + delta)
        alpha = 1 - np.exp(-t * rng.uniform(0.0, 1.0))
        new_f = evaluate(new_x)
        if new_f < best_f:
            x = new_x
            best_x = new_x.copy()
            best_f = new_f
        elif rng.rand() < alpha:
            beta = rng.normal(loc=1, scale=sigma / np.linalg.norm(delta))
            x = clip(x + (new_x - x) * beta)
        t *= 0.9999
    return best_x

